/**
 * Program types — Sawaa Dashboard
 *
 * Every RESPONSE shape is derived from the committed OpenAPI snapshot
 * (`lib/types/api.generated.ts`, regenerated by `pnpm openapi:sync`), so a
 * backend response change becomes a type error here instead of drifting
 * silently. `test/unit/lib/program-type-contract.spec.ts` pins that.
 *
 * Money: `price`/`depositAmount` are Prisma `Decimal` columns serialized with
 * `.toString()`, so they arrive as decimal strings and are converted with
 * `Number()` / `halalasStringToSar()` where arithmetic is needed.
 *
 * Request payloads are derived too, with one deliberate relaxation: the create
 * body marks `currency`, `depositEnabled` and `isPublic` as `default`-ed, which
 * makes the generated type require them, while the dashboard form may omit
 * them and let the server apply those same defaults.
 */

import type { components, paths } from "@/lib/types/api.generated"

type Schemas = components["schemas"]

/* ─── Entities (derived from OpenAPI) ─── */

/** Wire vocabulary of the program lifecycle (Prisma `ProgramStatus`). */
export type ProgramStatus = Schemas["ProgramListItemResponseDto"]["status"]

/** GET /dashboard/programs row: the persisted program plus `isFull` + `enrollmentCount`. */
export type ProgramSummary = Schemas["ProgramListItemResponseDto"]

/** GET /dashboard/programs/:id: the list row plus descriptions, supervisors and enrollments. */
export type ProgramDetail = Schemas["ProgramDetailResponseDto"]

/** One enrollment row on the detail payload, with its client name and booking. */
export type ProgramEnrollmentSummary = ProgramDetail["enrollments"][number]

/** GET /dashboard/programs/:id/cancellation-preview. */
export type ProgramCancellationPreview = Schemas["ProgramCancellationPreviewDto"]

/** PATCH /dashboard/programs/:id/cancel. */
export type ProgramCancellationResult = Schemas["ProgramCancellationResultDto"]

/** POST /dashboard/programs and PATCH /dashboard/programs/:id (identity + state only). */
export type ProgramWriteResult = Schemas["ProgramWriteResponseDto"]

/** PATCH /dashboard/programs/:id/publish. */
export type ProgramPublishResult = Schemas["ProgramPublishResponseDto"]

/** PATCH /dashboard/programs/:id/schedule. */
export type ProgramScheduleResult = Schemas["ProgramScheduleResponseDto"]

/* ─── Queries (derived from OpenAPI) ─── */

/** GET /dashboard/programs query surface: the route has no pagination params. */
export type ListProgramsQuery = NonNullable<
  paths["/api/v1/dashboard/programs"]["get"]["parameters"]["query"]
>

/* ─── Write payloads (derived from OpenAPI, one relaxation) ─── */

type CreateProgramBody = Schemas["CreateProgramDto"]

/**
 * POST /dashboard/programs body. `currency`/`depositEnabled`/`isPublic` are
 * optional here because the endpoint documents them with defaults (`default:
 * 'SAR'`, `default: false`), which openapi-typescript renders as required.
 */
export type CreateProgramPayload = Omit<
  CreateProgramBody,
  "currency" | "depositEnabled" | "isPublic"
> & {
  currency?: string
  depositEnabled?: boolean
  isPublic?: boolean
}

/** PATCH /dashboard/programs/:id body — every field optional, same field set. */
export type UpdateProgramPayload = Schemas["UpdateProgramDto"]

/** PATCH /dashboard/programs/:id/schedule body. */
export type ScheduleProgramPayload = Schemas["ScheduleProgramDto"]

/** PATCH /dashboard/programs/:id/cancel body; `refunds` is only sent after start. */
export type CancelProgramPayload = Schemas["CancelProgramDto"]

/* ─── Local-only payloads (their routes are outside this unit's contract) ─── */

/**
 * On-behalf enrollment: the program is a path parameter, so the body carries the
 * client only (`EnrollClientDto` rejects unknown fields). The enrollment route
 * creates a booking and an invoice, so it is intentionally not documented yet.
 */
export interface EnrollInProgramPayload {
  programId: string
  clientId: string
}

/** Result of `POST /dashboard/programs/:id/enrollments` (still undocumented). */
export interface EnrollInProgramResult {
  type: "ENROLLED"
  bookingId: string
  status: string
  invoiceId: string | null
}

/**
 * Public `/api/v1/public/programs` payload. Those routes belong to the public
 * unit and carry no response schema yet, so this shape stays hand-written and is
 * NOT derived from the dashboard snapshot.
 */
export interface PublicProgramListItem {
  id: string
  ref: number
  nameAr: string
  nameEn: string | null
  descriptionAr: string | null
  descriptionEn: string | null
  publicDescriptionAr: string | null
  publicDescriptionEn: string | null
  departmentId: string
  branchId: string
  startDate: string | null
  daysCount: number
  hoursPerDay: number
  minParticipants: number
  maxParticipants: number
  enrolledCount: number
  price: string
  currency: string
  depositEnabled: boolean
  depositAmount: string | null
  status: ProgramStatus
  isPublic: boolean
  supervisorIds: string[]
  isFull: boolean
  isOpenForEnrollment?: boolean
}
